capsule-structure.layout:
#[repr(C, align(128))]
pub struct PageTableCapsule {
    // === Coordination Fields (64 bytes, cache line 0) ===
    // DualAtomicU64 pattern for lockfree TLB coordination
    tlb_generation: AtomicU64,       // Even = valid TLB, odd = flush pending (8B)
    mapping_generation: AtomicU64,   // Incremented on every map/unmap (8B)

    // Page table metadata
    page_table_base: AtomicPtr<AtomicU64>, // GPU page table base address (8B)
    entry_count: AtomicU64,          // Number of valid PTEs (8B)

    // Statistics (lockfree counters)
    total_maps: AtomicU64,           // Total map operations (8B)
    total_unmaps: AtomicU64,         // Total unmap operations (8B)
    tlb_flushes: AtomicU64,          // Total TLB flushes (8B)
    page_faults: AtomicU64,          // Total page faults (8B)

    // === Padding (64 bytes, cache line 1) ===
    _padding: [u8; 64],              // Pad to 128 bytes (dual cache line)
}

verify_capsule_properties!(PageTableCapsule, 128, 128);

// Page Table Entry (PTE) - 64-bit packed format
// Bit layout: [phys_addr:40 | flags:8 | generation:16]
#[repr(transparent)]
pub struct PageTableEntry(AtomicU64);

impl PageTableEntry {
    // Packing: phys_addr (40 bits) | flags (8 bits) | gen (16 bits)
    pub fn pack(phys_addr: u64, flags: u8, gen: u16) -> u64 {
        (phys_addr & 0xFF_FFFF_FFFF) << 24 | (flags as u64) << 16 | (gen as u64)
    }

    pub fn unpack(entry: u64) -> (u64, u8, u16) {
        let phys_addr = (entry >> 24) & 0xFF_FFFF_FFFF;
        let flags = ((entry >> 16) & 0xFF) as u8;
        let gen = (entry & 0xFFFF) as u16;
        (phys_addr, flags, gen)
    }
}

api-design.trait-definition:
pub trait PageTableManager: Send + Sync {
    /// Map GPU virtual address to physical address (lockfree, <500ns)
    ///
    /// # Safety Invariants
    /// - I1 (Coherency): PTE write → TLB flush → GPU sees new mapping
    /// - I2 (Atomicity): PTE written atomically (64-bit Release store)
    /// - I5 (Use-After-Unmap): Refcount checked before unmap
    fn map(
        &self,
        gpu_va: u64,
        phys_addr: u64,
        size: usize,
        flags: PageFlags,
    ) -> Result<(), PageTableError>;

    /// Unmap GPU virtual address range (lockfree, <300ns)
    ///
    /// # Safety Invariants
    /// - I4 (TLB Consistency): Generation counter prevents stale TLB hits
    /// - I5 (Use-After-Unmap): Wait for refcount == 0 before unmap
    fn unmap(&self, gpu_va: u64, size: usize) -> Result<(), PageTableError>;

    /// Lookup physical address for GPU VA (lockfree, <20ns)
    ///
    /// # Returns
    /// - Some(mapping) if PTE valid and TLB generation matches
    /// - None if unmapped OR TLB flush pending (odd generation)
    fn lookup(&self, gpu_va: u64) -> Option<PhysicalMapping>;

    /// Invalidate TLB (lockfree flush protocol, <100ns)
    ///
    /// # Safety Invariants
    /// - I4 (TLB Consistency): Even→odd→flush→even protocol
    fn invalidate_tlb(&self) -> Result<(), PageTableError>;
}

api-design.implementation-sketch:
impl PageTableManager for PageTableCapsule {
    fn map(&self, gpu_va: u64, phys_addr: u64, size: usize, flags: PageFlags) -> Result<(), PageTableError> {
        // #ASSUME: Release ordering makes PTE visible before TLB flush
        // #VERIFY: Memory ordering validated via Loom model checker

        // 1. Calculate PTE index (4KB pages)
        let pte_index = (gpu_va >> 12) as usize;

        // 2. Load current mapping generation (TOCTOU prevention)
        let old_mapping_gen = self.mapping_generation.load(Ordering::Acquire);

        // 3. Create new PTE entry (phys_addr | flags | generation)
        let new_gen = (old_mapping_gen & 0xFFFF) as u16;
        let new_pte = PageTableEntry::pack(phys_addr, flags.bits(), new_gen);

        // 4. Atomic PTE update (lockfree CAS loop)
        let page_table = unsafe { &*self.page_table_base.load(Ordering::Acquire) };
        let pte = &page_table[pte_index];

        // CAS loop: retry if concurrent modification
        loop {
            let old_pte = pte.load(Ordering::Acquire);

            match pte.compare_exchange(
                old_pte,
                new_pte,
                Ordering::Release,  // Make PTE visible
                Ordering::Relaxed,
            ) {
                Ok(_) => break,
                Err(_) => continue,  // Retry on contention
            }
        }

        // 5. Increment mapping generation (TOCTOU detection)
        self.mapping_generation.fetch_add(1, Ordering::Release);

        // 6. Invalidate TLB (if needed)
        if flags.contains(PageFlags::FLUSH_TLB) {
            self.invalidate_tlb()?;
        }

        // 7. Update telemetry
        self.total_maps.fetch_add(1, Ordering::Relaxed);
        self.entry_count.fetch_add(1, Ordering::Relaxed);

        Ok(())
    }

    fn lookup(&self, gpu_va: u64) -> Option<PhysicalMapping> {
        // #ASSUME: Acquire ordering prevents load reordering
        // #VERIFY: TLB generation check prevents stale translation use

        // 1. Load TLB generation (check if flush pending)
        let tlb_gen = self.tlb_generation.load(Ordering::Acquire);
        if (tlb_gen & 1) != 0 {
            return None;  // TLB flush pending (odd generation)
        }

        // 2. Calculate PTE index
        let pte_index = (gpu_va >> 12) as usize;

        // 3. Load PTE entry (atomic read)
        let page_table = unsafe { &*self.page_table_base.load(Ordering::Acquire) };
        let pte = &page_table[pte_index];
        let pte_value = pte.load(Ordering::Acquire);

        // 4. Unpack PTE (phys_addr, flags, generation)
        let (phys_addr, flags, pte_gen) = PageTableEntry::unpack(pte_value);

        // 5. Validate PTE generation (stale TLB detection)
        let current_gen = (self.mapping_generation.load(Ordering::Acquire) & 0xFFFF) as u16;
        if pte_gen != current_gen {
            return None;  // Stale PTE (generation mismatch)
        }

        // 6. Return valid mapping
        Some(PhysicalMapping {
            phys_addr,
            flags: PageFlags::from_bits_truncate(flags),
            gpu_va,
            size: 4096,  // 4KB page
        })
    }

    fn invalidate_tlb(&self) -> Result<(), PageTableError> {
        // #ASSUME: Two-phase commit protocol prevents stale TLB use
        // #VERIFY: Even→odd→flush→even sequence validated in tests

        // Phase 1: Mark TLB flush pending (even → odd)
        let old_gen = self.tlb_generation.fetch_add(1, Ordering::Release);
        debug_assert_eq!(old_gen & 1, 0, "TLB generation must be even before flush");

        // Phase 2: Execute GPU TLB invalidate instruction
        self.execute_gpu_tlb_flush()?;

        // Phase 3: Mark TLB flush complete (odd → even)
        self.tlb_generation.fetch_add(1, Ordering::Release);

        // Update telemetry
        self.tlb_flushes.fetch_add(1, Ordering::Relaxed);

        Ok(())
    }
}

linux-i915-gtt.implementation:
pub struct I915PageTableCapsule {
    base: PageTableCapsule,  // Generic capsule fields
    gtt_base: *mut u64,       // GTT base pointer (memory-mapped)
    gtt_size: usize,          // GTT size in bytes
    mmio_base: *mut u32,      // MMIO base for TLB flush
}

impl PageTableManager for I915PageTableCapsule {
    fn execute_gpu_tlb_flush(&self) -> Result<(), PageTableError> {
        // Write to i915 TLB invalidate register (MMIO)
        unsafe {
            let tlb_reg = self.mmio_base.add(0x4260 / 4);  // GFX_FLSH_CNTL
            std::ptr::write_volatile(tlb_reg, 0x1);  // Trigger TLB flush
        }
        Ok(())
    }
}

capsule-os-generic.implementation:
pub struct CapsuleOSPageTableCapsule {
    base: PageTableCapsule,   // Generic capsule fields
    pml4_base: *mut AtomicU64, // Page Map Level 4 base
    page_size: usize,          // 4KB, 2MB, or 1GB
}

impl PageTableManager for CapsuleOSPageTableCapsule {
    fn execute_gpu_tlb_flush(&self) -> Result<(), PageTableError> {
        // Software TLB flush (atomic fence + syscall)
        std::sync::atomic::fence(Ordering::SeqCst);  // Memory barrier
        // Optional: Syscall to GPU driver for hardware TLB flush
        Ok(())
    }
}

