// Convert GTT memory-mapped region to AtomicU64 array (zero-copy)
let gtt_slice = unsafe { std::slice::from_raw_parts_mut(gtt_base, gtt_size / 8) };
let pte_array = AtomicU64::from_slice_mut(gtt_slice, 0)?;

// Direct atomic operations on GPU page table (no allocation)
pte_array[index].store(new_pte, Ordering::Release);
